const listCommercialTermsVersions = `-- name: ListCommercialTermsVersions :many
SELECT id, property_id, unit_id, version_no, permitted_uses, zoning_class, terms, actor_domain, actor_id, created_at FROM commercial_terms WHERE property_id = $1 ORDER BY created_at DESC, version_no DESC LIMIT 100
`

func (q *Queries) ListCommercialTermsVersions(ctx context.Context, db DBTX, propertyID ids.ID) ([]CommercialTerm, error) {
	rows, err := db.Query(ctx, listCommercialTermsVersions, propertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []CommercialTerm
	for rows.Next() {
		var i CommercialTerm
		if err := rows.Scan(
			&i.ID,
			&i.PropertyID,
			&i.UnitID,
			&i.VersionNo,
			&i.PermittedUses,
			&i.ZoningClass,
			&i.Terms,
			&i.ActorDomain,
			&i.ActorID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

